/* ÇEVİRİ fr · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("fr","olay",{
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Les Mamelouks battent les Dulkadırlı à Antep ; Besni revient sous administration mamelouke (approximatif)", "72742430"], "d": ["L'armée mamelouke vainquit les Dulkadırlı à Antep en 1436, et Mehmed Bey se retira à Akdağ. L'année du retour de Besni aux Mamelouks n'est pas écrite dans la source ; Besni avait été rattachée aux Dulkadır en 1418 et était revenue aux Mamelouks avant que Şehsuvar Bey ne la leur reprenne en 1465. L'atlas rend Besni aux Mamelouks avec cette défaite à Antep, centre voisin (approximation déclarée).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Dulkadıroğlu Şehsuvar Bey prend Besni aux Mamelouks (approximatif)", "843f0fc4"], "d": ["Şehsuvar Bey (1465-1472), nommé bey des Dulkadır par Mehmed le Conquérant, s'empara de Besni, Gerger, Birecik et Rumkale, aux mains des Mamelouks ; les Mamelouks furent battus à Turnadağı à l'automne 1467 et près d'Antep au printemps 1468.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["L'émir Yeşbek bat Şehsuvar Bey ; Besni revient sous administration mamelouke (approximatif)", "4d856aee"], "d": ["Au printemps 1471, l'émir Yeşbek vainquit Şehsuvar Bey sur la rivière Savron ; les Mamelouks reprirent Kadirli et Kozan. Şehsuvar fut exécuté au Caire en 1472, et les Mamelouks rétablirent Şahbudak à la tête de la principauté. Besni passa elle aussi sous administration mamelouke avec ce retour (TDV besni : « vers la fin du XVe siècle, elle retomba aux mains des Mamelouks »).", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Les forces de Ferdinand occupent et fortifient Szolnok", "6c8416e6"], "d": ["Alors que les Ottomans s'apprêtaient à bâtir une forteresse à Szolnok, sur la Tisza, les forces de Ferdinand Ier les devancèrent : elles occupèrent Szolnok à la mi-septembre 1550 et la forteresse fut mise en état de défense à la mi-octobre. Ainsi Szolnok, qui appartenait au pays d'Isabelle, passa aux mains des Habsbourg un an avant le passage de la Transylvanie à Ferdinand ; les Ottomans prirent la forteresse en 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["La Transylvanie passe sous administration habsbourgeoise : l'assemblée de Kolozsvár reconnaît l'abdication d'Isabelle", "8458a566"], "d": ["À la suite de l'accord de Martinuzzi avec Ferdinand, la reine Isabelle signa le 19 juin 1551 dans la forteresse de Szászsebes l'acte d'abdication qui lui était imposé, au nom du petit roi János Zsigmond. Le 26 juillet, l'assemblée de Transylvanie réunie à Kolozsvár reconnut cette abdication et l'autorité du roi Ferdinand ; l'armée habsbourgeoise du général Castaldo entra à Belgrade de Transylvanie (Gyulafehérvár). Ainsi la Transylvanie, vassale des Ottomans, passa à une administration habsbourgeoise qui allait durer cinq ans.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Fin de l'administration habsbourgeoise en Transylvanie : la Transylvanie redevient voïvodie vassale des Ottomans", "721a482a"], "d": ["János Zsigmond étant en bas âge, les Habsbourg tentèrent en 1551 de dominer la Transylvanie par l'entremise du prêtre d'origine croate Martinuzzi (Fráter György), nommé son tuteur ; Belgrade de Transylvanie (Gyulafehérvár), Kaloşvar, Brassó et Segesvár restèrent cinq ans sous administration habsbourgeoise. Les Ottomans empêchèrent cette situation et la Transylvanie redevint une voïvodie tributaire qui leur était rattachée. Aux XVIe et XVIIe siècles, la Transylvanie conserva ensuite pendant environ 150 ans un statut fondé sur une large autonomie dans ses affaires intérieures et sur l'allégeance à Istanbul dans ses affaires extérieures.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt et Tokaj passent du côté de Szapolyai", "587c782d"], "d": ["Après le retour d'Isabelle et de János Zsigmond en Transylvanie en 1556, les partisans de Szapolyai assiégèrent Nagyvárad en 1556. En 1557, les aristocrates de la haute Tisza s'emparèrent des plus importantes forteresses royales — Várad, Huszt et Tokaj ; seules Gyula et Világos restèrent aux mains de Ferdinand. Várad devint dès lors la forteresse de la principauté de Transylvanie et le resta jusqu'à sa prise par les Ottomans en 1660.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi prend Szatmár — l'extrémité nord de la Transylvanie passe aux Habsbourg", "2256bb27"], "d": ["Szatmár, passée aux Habsbourg en 1561 par le changement de camp de Balassa Menyhért, avait été reprise par surprise à l'automne 1564 par Báthory István et rattachée à la Transylvanie. Le commandant habsbourgeois Lazarus von Schwendi passa à la contre-offensive en février 1565 : Tokaj tomba le 9 février, Szerencs quatre jours plus tard, et Szatmár passa presque sans résistance aux forces impériales.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Les forces de Bocskai prennent Szatmár", "e93b098b"], "d": ["Tandis que le soulèvement de Bocskai s'étendait au nord-est de la Hongrie, Gyulaffy s'empara le 21 janvier 1605 de Szatmár, qu'il assiégeait. La paix de Vienne du 23 juin 1606 laissa le comitat de Szatmár à Bocskai à vie ; faute d'héritier mâle, le comitat revint à la couronne à la mort de Bocskai, le 29 décembre 1606.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Mort de Bocskai István — le comitat de Szatmár revient à la couronne", "3721bb9b"], "d": ["Le prince de Transylvanie Bocskai István mourut à Kassa le 29 décembre 1606. La paix de Vienne (23 juin 1606) lui avait laissé à vie les comitats, dont Szatmár, avec retour à la couronne à défaut d'héritier mâle ; par cette disposition, le comitat de Szatmár repassa au royaume de Hongrie des Habsbourg. La Transylvanie se mit en quête d'un nouveau prince.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Bethlen Gábor prend le comitat de Szatmár sous son contrôle", "80263da1"], "d": ["Avec la campagne de Bethlen Gábor en Hongrie à l'automne 1619, le comitat de Szatmár passa sous le contrôle du prince de Transylvanie ; en novembre 1619, il s'adressait au comitat par lettre. L'accord préliminaire du 23 janvier 1620 et la paix de Nikolsburg laissèrent à Bethlen à vie les sept comitats, dont Szatmár. Après la mort de Bethlen (15 novembre 1629), la restitution des comitats à la couronne fut achevée le 30 mars 1630.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Achèvement de la restitution à la couronne des sept comitats de Bethlen Gábor", "31b5968f"], "d": ["La paix de Nikolsburg avait laissé à Bethlen Gábor à vie sept comitats de la Haute-Hongrie, dont Szatmár. Après la mort de Bethlen le 15 novembre 1629, la restitution des comitats à la couronne commença par l'instruction du 30 novembre 1629 et fut achevée le 30 mars 1630.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["Rákóczi György Ier prend possession de Szatmár", "f398635b"], "d": ["Lors de la campagne de 1644 du prince de Transylvanie Rákóczi György Ier, la garnison allemande de Szatmár passa au service de Rákóczi et la forteresse tomba aux mains de la Transylvanie. La paix de Linz du 16 décembre 1645 laissa la forteresse aux héritiers de Rákóczi tant qu'un Rákóczi se trouverait sur le trône de Transylvanie.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Perte de Nitra — De Souches reprend la forteresse", "c71bf012"], "d": ["Nitra, qui s'était rendue après une brève résistance à la suite de la conquête d'Uyvar en 1663, fut assiégée le 15 avril 1664 par le commandant impérial De Souches ; la forteresse capitula le 3 mai 1664. Le traité de Vasvar ayant laissé les places conquises en l'état, Uyvar resta aux Ottomans tandis que Nitra resta aux mains des Habsbourg.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Perte de Léva", "f311920e"], "d": ["Après Nitra, De Souches assiégea Léva le 9 juin 1664 ; la capitulation fut signée le 13 juin et la forteresse était le 14 juin aux mains des forces impériales. La bataille de Léva (Garamszentbenedek) du 19 juillet 1664 ne changea pas la possession ; elle se termina par le maintien de Léva et de Nitra aux Habsbourg.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Dorochenko livre Tchyhyryn à Samoïlovytch", "3b538237"], "d": ["Petro Dorochenko, hetman de la rive droite sous protection ottomane, livra le 19 septembre 1676 sa capitale Tchyhyryn à l'hetman de la rive gauche Samoïlovytch et aux forces russes. Les Ottomans destituèrent Dorochenko et mirent à sa place Iouri Khmelnytsky ; le siège de 1677 pour chasser la garnison russe de Tchyhyryn échoua, et la forteresse ne fut prise que le 21 août 1678.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Remise des forteresses du Banat de Transylvanie (Temeşvar, Lippa, Lugos, Karánsebes) à Ferdinand, roi de Hongrie", "0e354976"], "d": ["En 1551, l'armée habsbourgeoise du général Castaldo entra en Transylvanie ; la reine Isabelle et son fils durent renoncer à leurs droits sur le trône de Hongrie. Avec l'accord de Castaldo, Martinuzzi envoya à la mi-juillet 1551 Báthory Endre prendre possession, au nom de Ferdinand, des forteresses de Temeşvar, Lippa, Solymos, Karánsebes, Lugos, Becse, Becskerek et Çanad. Les forteresses méridionales de la Transylvanie, placée sous protection ottomane, passèrent ainsi aux Habsbourg ; les campagnes de 1551-1552 de Soliman le Législateur en sont la réponse.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Nomination de Petrovics Péter comme sandjak-bey de Lugos et de Karánsebes", "bcbe73e4"], "d": ["À la demande insistante d'Isabelle et de Petrovics, Soliman le Législateur décida de ramener le petit János Zsigmond en Transylvanie. Par une lettre écrite d'Alep le 7 avril 1554, il ordonna aux Transylvains de ramener l'enfant dans son pays ; il enjoignit aussi aux voïvodes de Valachie et de Moldavie d'aider Petrovics, qu'il nomma à la même occasion sandjak-bey de Lugos et de Karánsebes. Lugos, conquise en 1552, fut ainsi confiée à Petrovics en tant que sandjak ottoman.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Levée du siège de Lippa — raid du ban de Lugos sur Temeşvar", "be03430e"], "d": ["Au printemps 1596, le pacha de Temeşvar assiégea Lippa. Dans la nuit du 10 au 11 mai, sur ordre de Palatics György, ban de Lugos pour la Transylvanie, les soldats de Buday György attaquèrent et incendièrent les faubourgs de Temeşvar ; le fait que Borbély György ait fait tirer tous les canons de la forteresse convainquit aussi le pacha que des secours arrivaient. Le 11 mai, le pacha se retira de devant Lippa et courut défendre son propre centre. Lugos était alors aux mains de la principauté de Transylvanie.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Occupation d'Orsova par les forces autrichiennes sous le commandement de Veterani", "1b4a4f6c"], "d": ["Lors de la campagne de 1688, le général Veterani, après avoir pris Karánsebes, marcha sur Orsova et l'occupa également. La source ne donne pas le jour de l'occupation ; le plancher de l'année, le 1er janvier 1688, a été utilisé.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Reprise d'Orsova par Thököly et les forces ottomanes", "c5645da9"], "d": ["Après la prise de Vetislan, Thököly et les pachas ottomans marchèrent sur Orsova, occupée par Veterani en 1688. À la suite d'escarmouches sans importance, Thököly entra à Orsova le 15 juillet 1689. Heissler, arrivé à la nouvelle du danger, constata que la force qui lui faisait face était bien équipée en munitions et en navires et se replia pour défendre la Transylvanie. En août, l'attaque d'Herbeville devant la ville ne parvint pas non plus à reprendre Orsova.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Le sandjak de Lugos tombe sous occupation habsbourgeoise (1691-1695)", "c8bcd6bd"], "d": ["Le sandjak de Lugos resta sous occupation habsbourgeoise (allemande) de 1691 à 1695 ; Mustafa II le reconquit le 22 septembre 1695. L'ancien enregistrement comportait un vide déclaré pour 1689-1695 ; la tranche 1691-1695 est désormais peinte en Habsbourg, 1689-1691 reste un vide. La date est prise comme année seule.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["La forteresse de Lugos passe sous administration habsbourgeoise", "6a9d401f"], "d": ["La forteresse-sandjak de Lugoj, rattachée à l'eyalet de Temeşvar, était aux mains des Ottomans depuis 1695 ; elle fut cédée à la monarchie des Habsbourg lors de la reddition du centre de l'eyalet au terme du siège de 1716. L'ancien enregistrement plaçait ce transfert au plancher de l'année, le 1er janvier 1716.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Prise d'Orsova par l'armée habsbourgeoise (campagne de 1717)", "7a4faffe"], "d": ["Lors de la campagne de 1717, le général Splényi parvint le 27 août devant Orsova et s'empara facilement de la ville ; Orsova, que Mercy n'avait pas pu prendre en 1716, passa ainsi aux Habsbourg. Les alvéoles riveraines du Danube alentour (y compris le secteur de Đerdap sur la rive serbe) dépendant du point d'habitat le plus proche, Orsova, ils sont peints de la couleur de son détenteur. La date est prise comme année seule ; le jour exact n'est pas confirmé.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Passage de la palanque d'Orsova aux Ottomans — repli du commandant sur Adakale", "de759b16"], "d": ["À l'ouverture de la campagne de 1738, Hacı Mehmed Pacha, gouverneur de Vidin, attaqua le retranchement d'Erzsébet sur le Danube. Le 8 mai, dans l'après-midi, un corps de 4 000 à 5 000 sipahis marcha de la rive gauche du Danube sur Orsova et attaqua la palanque d'Orsova ; le commandant autrichien, qui perdit une centaine d'hommes, se replia sur Nouvelle-Orsova, c'est-à-dire sur la forteresse insulaire d'Adakale. Après les combats de Mehadia en juillet, Adakale passa elle aussi aux Ottomans en août 1738 ; le traité de Belgrade de 1739 reconnut la situation.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Murad II prend Alacahisar, Niš et Şehirköy reviennent aux Ottomans", "54af926a"], "d": ["Après la mort sans héritier du despote serbe Stefan Lazareviç (1427), Murad II, se fondant sur le mariage de Bayezid Ier avec une princesse serbe, prétendit être l'héritier légitime de la Serbie et se mit en campagne ; il prit Alacahisar (1428). La même année, après la mort de Lazareviç, les Ottomans reprirent aussi la forteresse de Şehirköy — la ville avait été prise en 1412 par Stefan et défendue contre Mûsâ Çelebi. Selon l'article nis du TDV, les Ottomans reprirent aussi Niš la même année (831/1428). La ligne reliant les vallées de la Grande Morava et de la Nišava passa ainsi sous contrôle ottoman.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["L'armée des croisés prend Şehirköy — la branche de la Nišava de la « Longue Campagne »", "fdf6140c"], "d": ["L'armée des croisés dirigée par le roi Vladislav et le despote serbe Curac Brankoviç s'empara de Şehirköy en 1443. Dans la suite de la même campagne, les forces ottomanes seraient défaites en novembre au défilé d'Izladi. Şehirköy, rendue aux Serbes par Murad II après le traité de Szeged (1444), passa aux Ottomans en 1456, après la mort de Curac Brankoviç.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Domination ottomane définitive établie dans la région d'Alacahisar", "9715382a"], "d": ["Alacahisar, laissée à Brankoviç à l'issue du traité conclu en 1444 avec les délégués hongrois, repassa sous domination turque dans les années qui suivirent la victoire de Varna. Cette seconde conquête de la ville n'est pas attestée par un récit de guerre mais par un registre fiscal : les registres de timars de certains villages dépendant d'Alacahisar sont datés de fin 1453/début 1454 ; ce n'est toutefois qu'un témoignage villageois — en 1454, les forces ottomanes furent battues près d'Alacahisar, et en 1455 Alacahisar fut laissée à Brankoviç comme frontière. Selon le TDV, la domination ottomane définitive dans la région fut établie en 1458.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Fondation du despotat de Morée — Manuel Cantacuzène à Mistra", "87660b82"], "d": ["L'empereur byzantin Jean Cantacuzène donna à son fils Manuel une circonscription administrative distincte en Morée ; ainsi naquit le despotat de Morée, centré sur Mistra. Manuel gouverna jusqu'en 1380 ; durant cette période, la culture et l'art byzantins s'épanouirent particulièrement à Mistra. Le despotat dura jusqu'à la conquête de Mehmed II en 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Le despote Constantin reprend Patras aux Francs", "cb0dd18c"], "d": ["Constantin, despote de Morée (dernier empereur byzantin en 1449), reprit Patras aux Latins ; ce port important du nord-ouest de la péninsule fut ainsi lui aussi rattaché au despotat. Patras passa sous domination ottomane en 1458, lors de la campagne de Morée de Mehmed II.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić-Kosača « duc de Saint-Sava » — naissance de l'Herzégovine", "cc67061f"], "d": ["Stjepan Vukčić-Kosača, qui avait réuni Hum et Trebinje en une seule principauté, se révolta contre le roi de Bosnie et se proclama « Herceg (duc) de Saint-Sava » ; le titre lui fut conféré en 1448 par l'empereur Frédéric III. Le nom d'Herzégovine (« terre du Herceg ») vient de ce titre. L'Herzégovine passa à l'Empire ottoman par morceaux à partir de 1466, devint sandjak en 1470 ; ses terres restantes furent rattachées début 1482.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Paix de Cracovie — l'État de l'Ordre teutonique devient le duché de Prusse", "78666ddd"], "d": ["Albert de Brandebourg, grand maître de l'ordre des Chevaliers teutoniques, ne trouvant pas d'aide contre la Pologne, signa la paix de Cracovie. L'État de l'Ordre (Ordensstaat) devint, sous la suzeraineté de la Pologne, un duché héréditaire et séculier passé à la maison de Brandebourg. Le centre en était Königsberg ; Albert y fonda en 1544 l'université Albertina. Le duché devint royaume de Prusse en 1701.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Proclamation de la République d'Autriche — fin de la monarchie des Habsbourg", "c84f316c"], "d": ["Le lendemain du jour où l'empereur Charles Ier se retira des affaires de l'État, le 11 novembre, l'Assemblée nationale provisoire adopta la loi sur la forme de l'État et du gouvernement et la république fut proclamée. La Première République, centrée sur Vienne, remplaça l'Autriche des Habsbourg. Par cette proclamation, Vienne, Linz, Salzbourg, Innsbruck, Klagenfurt, Bregenz et les autres villes germano-autrichiennes devinrent territoire de la République d'Autriche (Deutschösterreich).", "2dcc1399"]},
"OLAYLAR_T5_1000A:1008-01-01:0":{"b": ["Batoumi sous la domination du royaume/des royaumes de Géorgie — témoignage daté de la source", "62cd2833"], "d": ["La source place la ville de Batoumi sous l'administration du royaume/des royaumes de Géorgie à cette date ; la possession antérieure n'est pas datée dans la source (l'atlas laisse vide la période précédant cette date).", "e03655c9"]},
"OLAYLAR_T5_1000A:1024-01-01:0":{"b": ["Le Marwanide Nasr al-Dawla rattacha Âmid à son émirat", "9fbc8c85"], "d": ["L'émir marwanide Nasr al-Dawla Ahmed rattacha Âmid (Diyarbekir) aux territoires de l'émirat ; l'année suivante, il prit aussi Urfa.", "d585a28b"]},
"OLAYLAR_T5_1000A:1054-01-01:0":{"b": ["Marâgha passa sous la domination seldjoukide", "c011cac9"], "d": ["Marâgha, aux mains des Revvâdides, passa sous la domination seldjoukide par la campagne de Tuğrul Bey en Azerbaïdjan.", "2ff74d2d"]},
"OLAYLAR_T5_1000A:1055-12-18:0":{"b": ["Tuğrul Bey entra à Bagdad", "38af55c2"], "d": ["Tuğrul Bey, venu à Bagdad sur l'invitation du calife Kāim-Biemrillâh, mit fin à la domination bouyide.", "f7f905d1"]},
"OLAYLAR_T5_1000A:1056-01-01:0":{"b": ["Mossoul passa aux mains des Seldjoukides", "20b8da93"], "d": ["Mossoul passa aux Seldjoukides avec l'Irak ; malgré la brève occupation de Basâsîrî, elle resta quatre ans aux mains des Seldjoukides.", "a55cff1d"]},
"OLAYLAR_T5_1000A:1061-01-01:0":{"b": ["Mossoul de nouveau aux Ukaylides", "8b7c0603"], "d": ["Mossoul passa de nouveau sous la domination ukaylide en 1061 ; après la prise seldjoukide de 1084, Melikşah rendit aussi la ville à l'émir ukaylide.", "71824a2b"]},
"OLAYLAR_T5_1000A:1064-01-01:0":{"b": ["Alparslan mit fin au shahisme de Nakhitchevan", "5620360e"], "d": ["Alparslan, ayant vaincu les Revvâdides, supprima le shahisme de Nakhitchevan fondé par les Dülefides.", "f9fd7d73"]},
"OLAYLAR_T5_1000A:1071-01-01:0":{"b": ["L'émir Saltuk conquit Erzurum", "f52c09dd"], "d": ["Après Manzikert, Alparslan concéda en iqta les environs d'Erzurum à l'émir Saltuk ; Saltuk prit la ville la même année et la principauté des Saltukides fut fondée (1080 selon Yinanç).", "505fcc25"]},
"OLAYLAR_T5_1000A:1071-01-01:1":{"b": ["Dânişmend Gazi conquit Sivas", "348d7ad3"], "d": ["Dânişmend Gazi, ayant pris Sivas qui lui avait été concédée en iqta après Manzikert, y fonda le noyau de la dynastie (la date de la conquête est discutée ; il existe aussi une tradition de 1080).", "b9b5dd65"]},
"OLAYLAR_T5_1000A:1074-01-01:0":{"b": ["Philarète s'empara de Malatya", "9c80e3bd"], "d": ["Philarète, qui avait fondé une principauté arménienne en Cilicie, prit Malatya en se faisant passer pour le représentant byzantin et l'administra par l'intermédiaire de gouverneurs (Gabriel et autres).", "958ede64"]},
"OLAYLAR_T5_1000A:1074-01-01:1":{"b": ["L'émir Dânişmend conquit Tokat", "c9321fb6"], "d": ["À la suite de la victoire de Manzikert, l'émir Dânişmend prit Tokat à Byzance.", "dcc7f8e2"]},
"OLAYLAR_T5_1000A:1085-01-01:0":{"b": ["Les Seldjoukides prirent Hasankeyf aux Marwanides", "4fa9d559"], "d": ["Du temps de Melikşah, les Seldjoukides mirent fin à la domination marwanide et prirent aussi Hasankeyf.", "b9794646"]},
"OLAYLAR_T5_1000A:1085-05-31:0":{"b": ["Le fils de Fahrüddevle prit Âmid, fin de la domination marwanide", "ecaf6b03"], "d": ["Zaîmürrüesâ, fils de Fahrüddevle İbn Cehîr, chargé par Melikşah, prit Âmid aux Marwanides.", "8745ce9d"]},
"OLAYLAR_T5_1000A:1093-01-01:0":{"b": ["Tutuş s'empara de Diyarbekir", "469b8ebc"], "d": ["Après la mort de Melikşah, Tutuş, prétendant au sultanat, prit la région de Diyarbekir et fit prisonnier Mansûr, dernier émir marwanide.", "52daa285"]},
"OLAYLAR_T5_1000A:1095-01-01:0":{"b": ["Un bey turkmène commença à régner à Âmid", "3d67b786"], "d": ["Après la mort de Tutuş, le bey turkmène Sadr domina Âmid ; son successeur İnal fonda la dynastie des İnaloğulları.", "5fdca35c"]},
"OLAYLAR_T5_1000A:1096-01-01:0":{"b": ["Kürboğa s'empara de Mossoul", "462a238f"], "d": ["L'émir seldjoukide Kürboğa prit Mossoul aux Ukaylides. (Dhou al-qa'da 489 / novembre 1096 ; l'atlas, se conformant à la notice, l'écrit avec une précision à l'année.)", "14d9ca6d"]},
"OLAYLAR_T5_1000A:1100-01-01:0":{"b": ["Niksar sous la domination des Danichmendides — témoignage daté de la source", "81181870"], "d": ["La source place la ville de Niksar sous l'administration des Danichmendides à cette date ; la possession antérieure n'est pas datée dans la source (l'atlas laisse vide la période précédant cette date).", "c1463e88"]},
"OLAYLAR_T5_1000A:1102-09-18:0":{"b": ["Le Danichmendide Gümüştegin Gazi prit Malatya", "87f1166c"], "d": ["Gümüştegin Gazi s'empara de Malatya au terme d'un siège.", "2d0e9668"]},
"OLAYLAR_T5_1000A:1106-09-02:0":{"b": ["Kılıç Arslan Ier reçut la reddition de Malatya", "eca366d5"], "d": ["Après la mort de Gümüştegin, Kılıç Arslan Ier rattacha Malatya au territoire seldjoukide par un siège de plus de deux mois.", "69bdbc2c"]},
"OLAYLAR_T5_1000A:1108-03-04:0":{"b": ["Le Mazyadide Sadaka mourut à Nu'maniye, Hilla aux Seldjoukides", "e5ecea7c"], "d": ["Muhammed Tapar vainquit Sadaka ; son fils Dübeys fut fait prisonnier et ne fut pas autorisé à retourner à Hilla.", "be1e2910"]},
"OLAYLAR_T5_1000A:1111-01-01:0":{"b": ["İlarslan reprit Elbistan à Tancrède", "923962c2"], "d": ["İlarslan, atabeg de Tuğrul Arslan, melik de Malatya, reprit Elbistan, que Tancrède, prince d'Antioche, avait prise.", "ce0754bd"]},
"OLAYLAR_T5_1000A:1112-01-01:0":{"b": ["L'Artukide Belek domina Harput", "83425a6e"], "d": ["Belek b. Behrâm, petit-fils d'Artuk Bey, domina Harput et fonda sa principauté dont le centre était Palu.", "ff838897"]},
"OLAYLAR_T5_1000A:1116-01-01:0":{"b": ["Niğde sous la domination de l'État seldjoukide d'Anatolie (de Turquie) — témoignage daté de la source", "dfb24c4b"], "d": ["La source place la ville de Niğde sous l'administration de l'État seldjoukide d'Anatolie (de Turquie) à cette date ; la possession antérieure n'est pas datée dans la source (l'atlas laisse vide la période précédant cette date).", "477146f3"]},
"OLAYLAR_T5_1000A:1117-01-01:0":{"b": ["Dübeys retourna à Hilla", "9bc0e03a"], "d": ["Après la mort de Muhammed Tapar, Dübeys put se rendre à Hilla du temps du sultan seldjoukide d'Irak Mahmud.", "d9aec87c"]},
"OLAYLAR_T5_1000A:1118-05-06:0":{"b": ["Mahmud est proclamé sultan seldjoukide d'Irak à Bagdad — fondation de l'État seldjoukide d'Irak", "18babf94"], "d": ["Après la mort de Muhammad Tapar, son fils Mahmud est proclamé sultan par le calife ; l'État seldjoukide d'Irak est fondé. Bagdad, ainsi que Mossoul et Tikrit, restent rattachées au sultanat seldjoukide d'Irak ; l'Azerbaïdjan (Maragha, Nakhitchevan) revient lui aussi à la part des Seldjoukides d'Irak. Selon la source, Tikrit figure cette année-là comme iqta' du shahna de Bagdad.", "cf36af86"]},
"OLAYLAR_T5_1000A:1119-01-01:0":{"b": ["Jean II Comnène reprend Denizli", "cb523c0f"], "d": ["L'empereur byzantin Jean II Comnène contraint Alp Kara, commandant seldjoukide à Laodicée, à se retirer ; le territoire de Denizli repasse à Byzance (la notice « bizans » donne 1120).", "8bdb49b8"]},
"OLAYLAR_T5_1000A:1120-01-01:0":{"b": ["Aksungur al-Ahmadili est envoyé à Maragha", "7a3d6deb"], "d": ["Le sultan Mahmud envoie Aksungur al-Ahmadili à Maragha ; l'atabegat des Ahmadilides s'installe dans la ville.", "3616b62c"]},
"OLAYLAR_T5_1000A:1124-12-10:0":{"b": ["L'émir danichmendide Ghazi prit possession de Malatya ; Elbistan passa aussi aux Danichmendides", "97f3f958"], "d": ["Après la mort de Belek, l'émir Ghazi prit, au terme d'un long siège, Malatya au prince seldjoukide Tughrul Arslan ; avec la conquête de la région de Malatya, Elbistan passa elle aussi sous l'administration danichmendide.", "ae95651d"]},
"OLAYLAR_T5_1000A:1127-01-01:0":{"b": ["L'émir Gazi prend Ankara aux Seldjoukides", "25b745cd"], "d": ["L'émir danishmendide Gazi bat Melik Arab, fils de Kılıç Arslan Ier, et lui prend Ankara.", "008f5e3f"]},
"OLAYLAR_T5_1000A:1127-01-01:1":{"b": ["Imad al-Din Zengi atabeg de Mossoul (Zengides)", "ba79276b"], "d": ["Le sultan seldjoukide d'Irak Mahmud concède Mossoul en iqta' à Imad al-Din Zengi ; l'atabegat de Mossoul est fondé.", "a1929772"]},
"OLAYLAR_T5_1000A:1134-01-01:0":{"b": ["Kayseri sous domination danishmendide — témoignage daté de la source", "3b9b8604"], "d": ["La source montre la ville de Kayseri sous l'administration des Danishmendides à cette date ; l'appartenance antérieure n'est pas datée dans la source (l'atlas laisse vide la période précédente).", "e82b707e"]},
"OLAYLAR_T5_1000A:1142-01-01:0":{"b": ["Kemah sous domination des Mengücüklüler (Mengücekoğulları) — témoignage daté de la source", "d86927c6"], "d": ["La source montre la ville de Kemah sous l'administration des Mengücüklüler (Mengücekoğulları) à cette date ; l'appartenance antérieure n'est pas datée dans la source (l'atlas laisse vide la période précédente).", "fcb6186c"]},
"OLAYLAR_T5_1000A:1144-01-01:0":{"b": ["Le sultan Mas'ud prend Elbistan", "825e2c56"], "d": ["Mas'ud Ier s'empare d'Elbistan et de Ceyhan, tenues par Aynüddevle, et nomme son fils Kılıç Arslan melik.", "d69cdacb"]},
"OLAYLAR_T5_1000A:1148-01-01:0":{"b": ["Nakhitchevan rattachée aux Eldiguzides", "774400cc"], "d": ["Avec la dislocation des Seldjoukides, Nakhitchevan est rattachée à l'État des Eldiguzides et en reste le centre jusqu'en 1174 (l'année du rattachement est sans année précise ; début de la dynastie).", "bf42d3bd"]},
"OLAYLAR_T5_1000A:1149-01-01:0":{"b": ["Tikrit passe aux Begteginides (EI2)", "a2caf5af"], "d": ["Selon ce que le TDV rapporte de l'EI2, Tikrit était sous la domination des Begteginides entre 1149 et 1190.", "d10d23e8"]},
"OLAYLAR_T5_1000A:1150-04-30:0":{"b": ["Le sultan Mas'ud donne Hilla à Salarkerd", "4bdbd034"], "d": ["Après la mort du Mazyadide Ali, le sultan Mas'ud donne Hilla à son commandant Salarkerd.", "059e9aeb"]},
"OLAYLAR_T5_1000A:1152-04-08:0":{"b": ["Mort du sultan Mas'ud ; le calife al-Muqtafi règne seul sur l'Irak et prend Hilla, Koufa et Wasit", "21192405"], "d": ["À la mort du sultan Mas'ud, le calife al-Muqtafi li-Amr Allah établit à Bagdad et en Irak une domination indépendante de l'influence seldjoukide ; le vizir du calife s'empare de Hilla, et Koufa et Wasit sont également conquises.", "cd348b82"]},
"OLAYLAR_T5_1000A:1156-01-01:0":{"b": ["Yağıbasan conquiert Elbistan", "824708d3"], "d": ["Après la mort de Mas'ud, le melik danishmendide de Sivas Yağıbasan prend Elbistan ; l'administration lui en est laissée par accord.", "d413e508"]},
"OLAYLAR_T5_1000A:1156-01-01:1":{"b": ["Les commandants seldjoukides prennent Hilla ; les Mazyadides soumis au délégué du sultan", "43afd955"], "d": ["Hilla est prise par les commandants du sultan Muhammad b. Mahmud ; les Mazyadides continuent de régner en tant que sujets du délégué du sultan.", "c6c81147"]},
"OLAYLAR_T5_1000A:1160-01-01:0":{"b": ["Bakou sous domination des Chirvanchahs — témoignage daté de la source", "1f2863e4"], "d": ["La source montre la ville de Bakou sous l'administration des Chirvanchahs à cette date ; l'appartenance antérieure n'est pas datée dans la source (l'atlas laisse vide la période précédente).", "506dae86"]},
"OLAYLAR_T5_1000A:1163-01-01:0":{"b": ["Le calife al-Mustandjid prend Hilla ; fin des Mazyadides", "4348923c"], "d": ["Les troupes du calife al-Mustandjid et des Banu Muntafiq occupent Hilla, et les Mazyadides sont dispersés.", "da071466"]},
"OLAYLAR_T5_1000A:1165-01-01:0":{"b": ["Kılıç Arslan II prend Elbistan et Darende", "7c109007"], "d": ["Profitant des querelles entre Danishmendides, Kılıç Arslan II s'empare de la région d'Elbistan, de Darende et de Gedük.", "d258bac6"]},
"OLAYLAR_T5_1000A:1172-01-01:0":{"b": ["Mleh le Roupénide reprend Tarse à Byzance", "2f98fd11"], "d": ["Avec l'aide de Nur al-Din Zengi, Mleh le Roupénide reprend Adana, Mopsueste (Misis) et Tarse aux Byzantins.", "e1cfa006"]},
"OLAYLAR_T5_1000A:1174-01-01:0":{"b": ["L'Eldiguzide Pehlivan prend Tabriz", "f0831f17"], "d": ["L'Eldiguzide Pehlivan prend pacifiquement Tabriz aux Ahmadilides et la donne à son frère Kızıl Arslan.", "81ee8ab8"]},
"OLAYLAR_T5_1000A:1175-01-01:0":{"b": ["Kılıç Arslan II prend Sivas et Niksar aux Danishmendides", "584575bb"], "d": ["Après la mort de Nur al-Din Zengi, Kılıç Arslan II conquiert à l'été 1175 Sivas, Niksar, Tokat et les autres territoires danishmendides ; la branche de Sivas prend fin.", "c8092aea"]},
"OLAYLAR_T5_1000A:1178-10-25:0":{"b": ["Kılıç Arslan II prend Malatya ; fin de la branche danishmendide", "3bdbb060"], "d": ["Au terme d'un siège de quatre mois, Malatya passe aux Seldjoukides et la branche de Malatya des Danishmendides prend fin.", "b92d6ebb"]},
"OLAYLAR_T5_1000A:1183-04-29:0":{"b": ["Saladin prend Amid et la donne à l'Ortokide Nur al-Din Muhammad", "8c3cc7bb"], "d": ["Saladin l'Ayyoubide assiège et prend Amid, donne Hısnıkeyfâ à l'émir ortokide Nur al-Din Muhammad ; les Inalides prennent fin.", "b16cdda4"]},
"OLAYLAR_T5_1000A:1184-01-01:0":{"b": ["Roupen III reprend Adana aux croisés", "e9876f85"], "d": ["Mopsueste (Misis), Adana et Tell Hamdun, passées un temps aux croisés après Mleh, sont reprises en 1184 par le Roupénide Roupen III.", "177b5432"]},
"OLAYLAR_T5_1000A:1190-01-01:0":{"b": ["Tikrit passe aux Abbassides", "e8f5aeac"], "d": ["Après la domination des Begteginides, la ville passe sous l'administration du califat abbasside.", "f91cfb0d"]},
"OLAYLAR_T5_1000A:1194-01-01:0":{"b": ["Rükneddin Süleyman Shah II reprend Samsun", "0971ebcd"], "d": ["Samsun et les territoires de la mer Noire orientale, passés aux Comnènes lors des querelles fratricides, sont repris par Süleyman Shah.", "940e4b5b"]},
"OLAYLAR_T5_1000A:1199-01-06:0":{"b": ["Adana et Tarse : la principauté roupénide devient le royaume arménien de Cilicie", "de3c4beb"], "d": ["La dynastie roupénide, qui tient Adana et Tarse, prend le titre royal ; il s'agit d'un changement de titre de la même dynastie, le territoire n'a pas changé de mains. Le jour du couronnement n'a PAS ÉTÉ TROUVÉ dans le TDV — la date a été reprise du début de la notice du royaume arménien de Cilicie (le jour de la notice n'est pas une source).", "be8faf2b"]},
"OLAYLAR_T5_1000A:1204-01-01:0":{"b": ["Fondation de l'empire grec de Trébizonde — Giresun et Sinope comprises dans ses frontières", "a99b6ba0"], "d": ["À la suite de la prise de Constantinople par les Latins, Alexis Comnène, réfugié à Trébizonde, se proclame empereur ; la ville devient le centre du nouvel État. L'État fondé par les petits-fils de Comnène, Alexis et David, s'étend jusqu'à Sinope ; Giresun reste également dans les frontières de l'empire grec de Trébizonde.", "dd95df25"]},
"OLAYLAR_T5_1000A:1204-04-13:0":{"b": ["Kütahya sous domination de l'empire de Nicée (Laskaris) — témoignage daté de la source", "d91fa405"], "d": ["La source montre la ville de Kütahya sous l'administration de l'empire de Nicée (Laskaris) à cette date ; l'appartenance antérieure n'est pas datée dans la source (l'atlas laisse vide la période précédente).", "50f100b1"]},
"OLAYLAR_T5_1000A:1205-01-01:0":{"b": ["L'Eldiguzide Abu Bakr prend Maragha", "03faed10"], "d": ["L'Ahmadilide Ala al-Din Körpe Arslan est contraint de céder la forteresse de Maragha à l'atabeg eldiguzide Abu Bakr.", "742aae78"]},
"OLAYLAR_T5_1000A:1206-01-01:0":{"b": ["Les Seldjoukides conquièrent Denizli et Honaz", "1053ccc8"], "d": ["Sous le second règne de Ghiyath al-Din Kaykhusraw Ier, Denizli et Honaz passent aux Seldjoukides (les sources byzantines donnent 1196, la notice « selcuklular » donne 603/1207).", "c102dae3"]},
"OLAYLAR_T5_1000A:1208-07-16:0":{"b": ["Ghiyath al-Din Kaykhusraw Ier rattache de nouveau Maraş aux Seldjoukides", "91b1544e"], "d": ["Kaykhusraw mène une campagne contre les Arméniens et rattache Maraş aux terres seldjoukides.", "5ffaa2f3"]},
"OLAYLAR_T5_1000A:1211-01-01:0":{"b": ["Kastamonu sous domination des Çobanoğulları — témoignage daté de la source", "10b682ba"], "d": ["La source montre la ville de Kastamonu sous l'administration des Çobanoğulları à cette date ; l'appartenance antérieure n'est pas datée dans la source (l'atlas laisse vide la période précédente).", "1cdb9e90"]},
"OLAYLAR_T5_1000A:1214-11-02:0":{"b": ["Izz al-Din Kaykaus Ier conquiert Sinope", "463ea2b9"], "d": ["Le sultan seldjoukide Izz al-Din Kaykaus Ier prend Sinope aux Comnènes de Trébizonde.", "0a71d5c6"]},
"OLAYLAR_T5_1000A:1222-01-01:0":{"b": ["Ala al-Din Kayqubad Ier prend Kalonoros (Alaiye)", "5a4d6ac2"], "d": ["La forteresse de Kalonoros, à l'est d'Antalya, est prise par les Seldjoukides, reconstruite et reçoit le nom d'Alaiye (la notice « alanya » donne 1221).", "a00756da"]},
"OLAYLAR_T5_1000A:1225-01-01:0":{"b": ["Djalal al-Din le Khwarezmchah annexe l'Azerbaïdjan", "5b812b99"], "d": ["Djalal al-Din le Khwarezmchah rattache l'Azerbaïdjan et l'Arrân à ses terres (phrase de portée régionale).", "5bba4780"]},
"OLAYLAR_T5_1000A:1225-07-01:0":{"b": ["Djalal al-Din le Khwarezmchah prend Maragha", "a55ec004"], "d": ["Djalal al-Din le Khwarezmchah s'empare de Maragha et en fait son centre militaire et administratif en Azerbaïdjan.", "2aa8a852"]},
"OLAYLAR_T5_1000A:1225-07-25:0":{"b": ["Djalal al-Din le Khwarezmchah entre à Tabriz", "72904097"], "d": ["Lorsque l'atabeg Özbek se replie sur Gandja, Djalal al-Din le Khwarezmchah entre à Tabriz, y établit sa domination et en fait son centre.", "43ee9867"]},
"OLAYLAR_T5_1000A:1228-01-01:0":{"b": ["Ala al-Din Kayqubad prend Kemah", "8c5aa655"], "d": ["La branche de Kemah-Erzincan des Mengücüklüler est rattachée aux terres seldjoukides par Ala al-Din Kayqubad Ier, qui assiège et prend Kemah.", "7edb7223"]},
"OLAYLAR_T5_1000A:1231-01-01:0":{"b": ["Maragha est prise par les Mongols pour la seconde fois", "f1320e5d"], "d": ["À la fin de la domination khwarezmienne, Maragha tombe aux mains des Mongols.", "9cee2a89"]},
"OLAYLAR_T5_1000A:1231-01-01:1":{"b": ["L'Azerbaïdjan passe sous domination mongole — Tabriz subit l'occupation mongole", "3f38ef66"], "d": ["Avec l'effondrement de Djalal al-Din le Khwarezmchah, Tabriz subit l'occupation mongole en 1231 ; la domination mongole englobe la même année l'Azerbaïdjan du Nord et du Sud (phrase de portée régionale, non propre à la ville). À Chirvan (Bakou, Chamakhi), les Chirvanchahs subsistent comme dynastie locale sous la souveraineté mongole ; l'atlas maintient ces deux points à la couleur chirvanchah sur décision d'Emre (la vassalité mongole/ilkhanide figure dans la note).", "46225c2e"]},
"OLAYLAR_T5_1000A:1232-10-01:0":{"b": ["L'Ayyoubide al-Malik al-Kamil prend Amid", "9cebe681"], "d": ["Al-Malik al-Kamil assiège Amid et la prend aux Ortokides.", "02085ee1"]},
"OLAYLAR_T5_1000A:1233-01-01:0":{"b": ["Ala al-Din Kayqubad Ier prend Kütahya à l'empire de Nicée", "e0b9a7f7"], "d": ["Kütahya, repassée à Byzance lors des troubles postérieurs à 1182, est reprise à l'empire de Nicée à l'époque d'Ala al-Din Kayqubad Ier.", "90db8b27"]},
"OLAYLAR_T5_1000A:1233-01-01:1":{"b": ["Badr al-Din Lu'lu' sultan de Mossoul", "73268628"], "d": ["À la mort du dernier atabeg zengide, Badr al-Din Lu'lu' est proclamé sultan par le calife. (Rabi' al-awwal 631 / décembre 1233 ; l'atlas, suivant la notice, l'écrit à la précision de l'année.)", "076b23b0"]},
"OLAYLAR_T5_1000A:1234-08-01:0":{"b": ["Les Seldjoukides prennent Harput", "3b9391eb"], "d": ["L'armée d'Ala al-Din Kayqubad reçoit la reddition de la forteresse de Harput au terme d'un siège de vingt-quatre jours ; les Ortokides de Harput prennent fin.", "1ae6c0d9"]},
"OLAYLAR_T5_1000A:1240-07-23:0":{"b": ["Ghiyath al-Din Kaykhusraw II conquiert Amid", "c37c3b04"], "d": ["Le sultan seldjoukide d'Anatolie Ghiyath al-Din Kaykhusraw II prend Amid aux Ayyoubides.", "f8a0cc8c"]},
"OLAYLAR_T5_1000A:1253-01-01:0":{"b": ["Möngke Khan nomme Iftikhar al-Din gouverneur de Qazvin", "fc650d13"], "d": ["Le Grand Khan mongol Möngke nomme un gouverneur à Qazvin ; l'époque des Iftikharides commence.", "c042dadd"]},
"OLAYLAR_T5_1000A:1256-01-01:0":{"b": ["Arrivée de Hülegü : Qazvin et Nakhitchevan passent à l'administration ilkhanide", "24673608"], "d": ["Avec l'arrivée de Hülegü en Iran, l'administration mongole passe à l'État ilkhanide ; Qazvin et Nakhitchevan passent sous administration ilkhanide (limite de la règle 5, non un jour de source). À Chirvan (Bakou, Chamakhi), l'occupation mongole entraîne de lourdes destructions, mais les Chirvanchahs se maintiennent comme dynastie locale ; l'atlas maintient ces deux points à la couleur chirvanchah (décision d'Emre).", "14d75e4f"]},
"OLAYLAR_T5_1000A:1257-01-01:0":{"b": ["Les Mongols occupent Tikrit", "60af2df0"], "d": ["Lors de l'invasion mongole, Tikrit est occupée et pillée ; la ville sort de l'administration abbasside.", "1a51fdd7"]},
"OLAYLAR_T5_1000A:1257-03-27:0":{"b": ["Hülegü marche de Hamadan sur Bagdad", "5f0c77b5"], "d": ["Hülegü part de Hamadan, où se trouvaient ses bagages, pour la campagne de Bagdad (témoin de la domination ilkhanide).", "303cbae8"]},
"OLAYLAR_T5_1000A:1258-01-01:0":{"b": ["Bughatimur prend Koufa et Bassorah", "dec82b4e"], "d": ["Les forces mongoles placées sous Bughatimur s'emparent de Koufa, de Wasit et de Bassorah.", "10fd1496"]},
"OLAYLAR_T5_1000A:1258-01-01:1":{"b": ["L'Irak passe aux mains des Mongols (régional)", "7b990281"], "d": ["Avec l'occupation de Bagdad par Hülegü en 1258, l'État abbasside est détruit et l'Irak passe aux mains des Mongols.", "6f12d882"]},
"OLAYLAR_T5_1000A:1258-01-01:2":{"b": ["Maraş est abandonnée aux Arméniens", "6161f1a5"], "d": ["Faute de soutien, Imad al-Din, de la famille de Husam al-Din, abandonne Maraş aux Arméniens de Cilicie.", "9ea1e7ff"]},
"OLAYLAR_T5_1000A:1258-01-01:3":{"b": ["Wasit passe sous domination ilkhanide", "fbdf83fc"], "d": ["Avec la conquête de l'Irak par les Ilkhanides, Wasit entre sous leur administration.", "5f4aee6b"]},
"OLAYLAR_T5_1000A:1258-02-10:0":{"b": ["Les Mongols prennent Bagdad ; fin du califat abbasside", "41c34bd4"], "d": ["Les Mongols commandés par Hülegü attaquent Bagdad, le calife al-Musta'sim se rend ; la ville passe sous domination ilkhanide.", "1c979d91"]},
"OLAYLAR_T5_1000A:1262-01-01:0":{"b": ["Les Mongols prennent Mossoul, fin de la dynastie des Lu'lu'ides", "035d0121"], "d": ["Mossoul d'al-Malik al-Salih Isma'il, qui s'était rangé aux côtés de Baybars, subit les destructions mongoles, et lui-même est mis à mort en présence de Hülegü.", "69cc41a9"]},
"OLAYLAR_T5_1000B:1069-10-20:0":{"b": ["La khutba de La Mecque est dite au nom du calife abbasside et du sultan Alp Arslan, et non plus des Fatimides", "df951887"], "d": ["La famine d'Égypte ayant interrompu l'arrivée des vivres, l'émir de La Mecque Abu Hashim Muhammad b. Dja'far fait dire la khutba au nom du calife abbasside al-Qa'im bi-Amr Allah et du sultan seldjoukide Alp Arslan ; La Mecque passe sous la suzeraineté des Grands Seldjoukides.", "c8a5b1f7"]},
"OLAYLAR_T5_1000B:1075-01-01:0":{"b": ["Atsiz b. Uvak prend Damas", "8eea047f"], "d": ["Atsiz s'empare de la Syrie et fait dire la khutba au nom du calife abbasside et de Malik Shah.", "1de51f0c"]},
"OLAYLAR_T5_1000B:1076-01-01:0":{"b": ["L'émir de La Mecque Abu Hashim fait de nouveau dire la khutba au nom du calife fatimide", "85b6c0c0"], "d": ["Malgré les efforts de Malik Shah pour consolider l'influence sunnite, l'émir de La Mecque recommence à faire dire la khutba au nom des Fatimides ; La Mecque revient à la suzeraineté fatimide.", "a7ec64c5"]},
"OLAYLAR_T5_1000B:1079-01-01:0":{"b": ["Tutuş entre à Damas, fondation des Seldjoukides de Syrie", "b48b38be"], "d": ["Tutuş entre dans la ville et fonde l'État seldjoukide de Syrie.", "6404e098"]},
"OLAYLAR_T5_1000B:1080-01-01:0":{"b": ["L'émir de La Mecque proclame son allégeance au calife abbasside al-Muqtadi et au sultan Malik Shah", "38a430a5"], "d": ["L'émir de La Mecque se soumet de nouveau au calife abbasside et au sultan seldjoukide ; cette allégeance dure jusqu'à la mort de Malik Shah (1092).", "41ad14e9"]},
"OLAYLAR_T5_1000B:1092-01-01:0":{"b": ["À la mort du sultan Malik Shah, la khutba de La Mecque revient aux Fatimides", "195a27cd"], "d": ["À la mort du sultan seldjoukide Malik Shah, l'émir de La Mecque recommence à faire dire les khutba au nom du calife fatimide ; La Mecque passe à la suzeraineté fatimide.", "00e9a74b"]},
"OLAYLAR_T5_1000B:1097-07-01:0":{"b": ["Après la défaite de Dorylée, Eskişehir revient à Byzance", "3f381ee4"], "d": ["Après le repli de Kılıç Arslan Ier devant les croisés, la ville repasse sous administration byzantine.", "f3155b07"]},
"OLAYLAR_T5_1000B:1104-06-06:0":{"b": ["Toghtekin fonde l'atabegat de Damas", "f26729c0"], "d": ["Après la mort de Duqaq, l'atabeg Toghtekin fonde la dynastie des Bourides.", "ac9e7419"]},
"OLAYLAR_T5_1000B:1150-01-01:0":{"b": ["Les Almohades prennent Meknès", "ee976b41"], "d": ["Après une longue résistance, la ville passe sous domination almohade et est pillée.", "4924b727"]},
"OLAYLAR_T5_1000B:1154-04-25:0":{"b": ["Nur al-Din Zengi prend Damas", "a4fd8b58"], "d": ["Nur al-Din Mahmud place Damas sous sa domination.", "f87fe7de"]},
"OLAYLAR_T5_1000B:1171-09-13:0":{"b": ["Fin de l'administration fatimide en Égypte, les Ayyoubides prennent le pouvoir — Alexandrie, Fayoum et La Mecque (Hedjaz)", "1c565534"], "d": ["Avec le vizirat de Saladin et la mort du calife fatimide al-Adid (567/1171), l'Égypte passe aux Ayyoubides ; Alexandrie et le Fayoum entrent sous administration ayyoubide. Le jour est absent de la source — repris de la fin de la notice fatimide (le jour de la notice n'est pas une source). Le Hedjaz passe lui aussi sous administration ayyoubide ; la suzeraineté de La Mecque passe des Fatimides aux Ayyoubides (modèle de suzeraineté d'Emre n° 23).", "191ac5be"]},
"OLAYLAR_T5_1000B:1174-01-01:0":{"b": ["Saladin prend Damas", "dfdb11ce"], "d": ["Après la mort de Nur al-Din, la ville passe à Saladin l'Ayyoubide.", "a20855b8"]},
"OLAYLAR_T5_1000B:1176-09-17:0":{"b": ["Après Myriokephalon, Byzance évacue Dorylée", "24aef255"], "d": ["Après la défaite de Myriokephalon, Manuel fait raser, conformément au traité, les fortifications de Dorylée et évacue la ville ; les Turcs commencent à l'appeler Eskişehir.", "d56a7724"]},
"OLAYLAR_T5_1000B:1178-01-01:0":{"b": ["Amasya rattachée aux terres seldjoukides", "cf56b964"], "d": ["Kılıç Arslan II rattache les terres danishmendides (Amasya comprise) au pays seldjoukide.", "ddbb98aa"]},
"OLAYLAR_T5_1000B:1187-01-01:0":{"b": ["Les frères Asen prennent la Bulgarie du Nord ; Byzance reconnaît le Second État bulgare", "ff0554e9"], "d": ["Les frères Petar et Asen reprennent la Bulgarie du Nord avec l'appui des Coumans ; par la paix de 1187, Byzance reconnaît le Second État bulgare.", "fc165cbf"]},
"OLAYLAR_T5_1000B:1189-01-01:0":{"b": ["La Serbie consolide sa domination sur la Zeta", "794c821d"], "d": ["En 1189, la Serbie consolide sa domination sur la Zeta (littoral de Kotor compris) ; un statut particulier est reconnu à la Zeta.", "5f16f312"]},
"OLAYLAR_T5_1000B:1192-01-01:0":{"b": ["Guy de Lusignan achète Chypre, Nicosie devient capitale", "11017aea"], "d": ["Guy de Lusignan achète l'île aux Templiers et fait de Nicosie la capitale.", "b6494b99"]},
"OLAYLAR_T5_1000B:1201-03-01:0":{"b": ["Kaloyan s'empare de Varna", "1237fe7f"], "d": ["Les Bulgares sous le commandement du tsar Kaloyan prennent Varna à Byzance en mars 1201 ; la ville reste dans les frontières de l'État bulgare aux XIIIe-XIVe siècles.", "b60444f8"]},
"OLAYLAR_T5_1000B:1202-01-01:0":{"b": ["Nichapour définitivement rattachée aux Khwarezmchahs", "fa4a6cd2"], "d": ["Ala al-Din Muhammad b. Tekish rattache définitivement la ville aux terres khwarezmchahs.", "58cb9059"]},
"OLAYLAR_T5_1000B:1204-04-13:0":{"b": ["La péninsule de Gallipoli passe sous administration latine", "27308f59"], "d": ["À la suite de la quatrième croisade, Gallipoli et sa région passent en 1204 sous l'administration des Latins.", "48b977ad"]},
"OLAYLAR_T5_1000B:1204-04-13:1":{"b": ["Fondation du despotat d'Épire — Ioannina en devient le centre, Naupacte passe au despotat", "d7966877"], "d": ["À la suite de la quatrième croisade, Michel Ange fonde le despotat d'Épire ; Ioannina devient le centre du despotat, et Naupacte reste également dans les terres du despotat.", "632eac4c"]},
"OLAYLAR_T5_1000B:1204-08-12:0":{"b": ["La Crète est vendue à Venise", "f1760e84"], "d": ["Par l'accord du 12 août 1204, Boniface, marquis de Montferrat, cède la Crète à Venise pour 100 000 pièces d'argent.", "cdb2570d"]},
"OLAYLAR_T5_1000B:1219-01-01:0":{"b": ["Fondation de Mansourah", "342a6f47"], "d": ["Al-Malik al-Kamil fonde Mansourah comme camp contre les croisés qui occupent Damiette.", "35189819"]},
"OLAYLAR_T5_1000B:1221-04-10:0":{"b": ["Les Mongols prennent Nichapour", "0e73f075"], "d": ["La ville est détruite par l'invasion mongole.", "be55c768"]},
"OLAYLAR_T5_1000B:1229-01-01:0":{"b": ["Le Rasulide Nur al-Din Umar place le Yémen sous son administration", "ee1ec7ab"], "d": ["Après la mort d'al-Mas'ud, dernier Ayyoubide du Yémen, Nur al-Din Umar s'assure la domination du Yémen.", "02cf9719"]},
"OLAYLAR_T5_1000B:1235-01-01:0":{"b": ["L'empereur de Nicée Vatatzès reprend Gallipoli", "a6936e33"], "d": ["L'empereur de Nicée Jean III Vatatzès reprend Gallipoli aux Latins (1235).", "184a089e"]},
"OLAYLAR_T5_1000B:1243-07-01:0":{"b": ["Les Mongols s'emparent d'Amasya", "783bcd0c"], "d": ["Après Köse Dağ, les Mongols prennent la ville, qui est administrée par des gouverneurs mongols.", "4e46e2df"]},
"OLAYLAR_T5_1000B:1246-01-01:0":{"b": ["Vatatzès passe en Thrace : Andrinople et Thessalonique rattachées à l'empire de Nicée", "0bf61ca5"], "d": ["Le souverain de Nicée Jean III Vatatzès passe en Thrace en 1246 et s'empare des terres occupées par les Bulgares ainsi que de Thessalonique.", "73992921"]},
"OLAYLAR_T5_1000B:1250-01-01:0":{"b": ["La domination rasulide est reconnue à La Mecque — Nur al-Din Umar victime d'un assassinat", "d7e03c21"], "d": ["Lorsque le sultan rasulide du Yémen Nur al-Din Umar est assassiné à Janad (février 1250), la domination de son État était reconnue entre La Mecque et le Hadramaout ; l'année où prend fin le sultanat ayyoubide, La Mecque apparaît sous la suzeraineté rasulide.", "ba654624"]},
"OLAYLAR_T5_1000B:1250-04-30:0":{"b": ["Fondation de l'État mamelouk en Égypte — Alexandrie, Mansourah et le Fayoum passent aux Mamelouks", "230c1a11"], "d": ["Après Turanshah, le pouvoir mamelouk est établi avec Shajar al-Durr et Izz al-Din Aybak ; les villes d'Égypte (Alexandrie, Mansourah, Fayoum) passent sous administration mamelouke. La source donne l'avènement d'Aybak au 3 juillet 1250 ; l'atlas a repris le jour de la fin de la notice ayyoubide (30 avril 1250) — le jour de la notice n'est pas une source, l'écart est signalé.", "f9743bcd"]},
"OLAYLAR_T5_1000B:1250-04-30:1":{"b": ["L'Ayyoubide d'Alep al-Nasir Yusuf devient maître de Damas", "d585985d"], "d": ["Alors que le pouvoir mamelouk s'établit en Égypte, le maître d'Alep al-Nasir Yusuf prend Damas (648/1250).", "c05ddddc"]},
"OLAYLAR_T5_1000B:1253-04-01:0":{"b": ["Jérusalem est cédée aux Mamelouks par la paix", "50d53fac"], "d": ["Par la paix conclue par l'intermédiaire du calife, Jérusalem est cédée aux Mamelouks.", "82982e3a"]},
"OLAYLAR_T5_1000B:1256-01-01:0":{"b": ["Jérusalem repasse aux Ayyoubides", "fdeedd4a"], "d": ["La Palestine et Jérusalem retombent aux mains des Ayyoubides de Syrie.", "46a6e2a9"]},
"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["Les Mongols prennent Damas", "430bdfea"], "d": ["Lors de la campagne de Hülegü en Syrie, Damas passe aux Mongols.", "407e5d3f"]},
"OLAYLAR_T5_1000B:1260-09-03:0":{"b": ["Bataille d'Aïn Djalout : Damas et Jérusalem passent aux Mamelouks", "40ebd7b7"], "d": ["Qutuz bat les Mongols à Aïn Djalout (25 ramadan 658 / 3 septembre 1260) ; la plus grande partie de la Syrie, Damas et Jérusalem passent aux mains des Mamelouks, et la dynastie ayyoubide prend fin.", "619c8015"]},
"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["Baybars rétablit le califat abbasside au Caire — La Mecque et Médine rattachées aux Mamelouks", "a5128a1e"], "d": ["Baybars proclame calife au Caire l'Abbasside Ahmad, rescapé de la destruction de Bagdad, et lui prête serment ; en tant que protecteur du califat, il rattache aussi les Lieux saints (Haramayn) à la suzeraineté mamelouke. Le jour est celui du rétablissement du califat ; le jour du rattachement de La Mecque et de Médine est absent de la source (borne inférieure).", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["Les troupes de Nicée entrent à Constantinople — l'Empire byzantin est rétabli", "81741490"], "d": ["Les troupes de Nicée entrent à Constantinople le 25 juillet 1261 et mettent fin à la domination latine ; les territoires de l'État laskaride (de Nicée) — Bursa, Izmir, Çimpe, Andrinople, Thessalonique — redeviennent l'Empire byzantin. En ces points, l'atlas ne montre la période de l'empire de Nicée antérieure à 1261 que pour ceux qui y figurent nommément dans la source.", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["Charles d'Anjou prend Durazzo et Krujë", "082a86b8"], "d": ["Charles, de la dynastie d'Anjou, prend Durazzo et Krujë en 1271-1272 et fait reconstruire l'ancienne forteresse.", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["Les Siciliens occupent l'île de Djerba", "daab5ad2"], "d": ["L'île de Djerba est occupée par les Siciliens en l'an 683 (1284-85) ; d'abord domaine de la papauté, elle dépend ensuite du royaume de Sicile.", "691035b3"]},
"OLAYLAR_T5_1000B:1318-01-01:0":{"b": ["Ioannina est de nouveau rattachée à l'Empire byzantin", "60016303"], "d": ["Ioannina, qui avait changé de mains à de nombreuses reprises dans la seconde moitié du XIIIe siècle, est de nouveau rattachée à Byzance en 1318, tout en conservant une certaine autonomie ; le centre du despotat d'Épire se déplace à Arta.", "14c24d12"]},
"OLAYLAR_T5_1000B:1334-01-01:0":{"b": ["Les habitants de Djerba chassent les Siciliens de l'île", "ff71985e"], "d": ["Les habitants de l'île, soulevés contre la mauvaise administration des gouverneurs siciliens, chassent les Siciliens en 1334 ; Djerba repasse sous administration hafside.", "1ddb9780"]},
"OLAYLAR_T5_1000B:1363-01-01:0":{"b": ["Charles Thopia devient maître de Krujë", "4e40583d"], "d": ["Après la mort du tsar Dušan (1355), l'Albanais Charles Thopia devient maître de Krujë.", "7af64cd2"]},
"OLAYLAR_UMIT19_ASIRET_1119:1722-04-05:0":{"b": ["Roggeveen aperçut l'île de Pâques et la nomma Paasch Eyland ; la présence d'habitants fut déduite le lendemain des fumées", "c6940261"], "d": ["D'après le journal de bord officiel, l'expédition de Jacob Roggeveen aperçut le 5 avril 1722 une île basse et plate et, comme c'était le jour de Pâques, lui donna le nom de Paasch Eyland. Le 6 avril, des fumées s'élevant en divers endroits furent observées et l'on en conclut que l'île était habitée ; le récit de Behrens place la découverte au 6 avril.", "32641f88"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-08-13:0":{"b": ["Les troupes d'avant-garde de l'expédition Sullivan incendient le village de Chemung (Chemong)", "2656fcd6"], "d": ["L'armée de Sullivan quitta Tioga dans la soirée du 12 août 1779 pour une marche de nuit et atteignit le village de Chemung à l'aube du lendemain ; les villageois avaient fui auparavant. Les troupes incendièrent une vingtaine de bâtiments du village et détruisirent les champs de maïs environnants.", "07caaa80"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-08-29:0":{"b": ["Bataille de Newtown : l'expédition de Sullivan délogea les guerriers iroquois, dont des Cayugas et des Sénécas, de leur retranchement près de Chemung", "2383ea65"], "d": ["Le 29 août 1779, l'armée du major général Sullivan rencontra près de Chemung un retranchement préparé par des forces composées en majorité, selon la lettre de Sullivan, de guerriers indiens des « sept nations » (avec les commandements distincts des Butler, de Brant et de McDonald) ; sous le feu de l'artillerie et la pression sur le flanc exercée par le général Poor, le retranchement fut abandonné.", "3adfc9de"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-09-02:0":{"b": ["L'armée de Sullivan détruisit le village de Catharine's Town et son maïs", "62b91293"], "d": ["L'armée de l'expédition de Sullivan parvint à Catharine's Town, près du lac Seneca, dans la nuit du 1er septembre 1779 ; le 2 septembre, elle détruisit le village et le maïs cultivé. Le village était un établissement de trente maisons, avec des jardins et du maïs en abondance.", "d56e8155"]},
"OLAYLAR_UMIT19_ASIRET_1119:1830-10-07:0":{"b": ["L'opération de la Ligne noire (Black Line) commença en Terre de Van Diemen : les colons furent mobilisés pour capturer les Aborigènes de Tasmanie", "d2ffdfcb"], "d": ["L'avis du secrétariat colonial du gouverneur Arthur, daté du 25 septembre 1830, annonça que la population se mettrait en mouvement en masse le 7 octobre 1830 et que le major Douglas occuperait le même jour les postes le long de la ligne. Le but était de capturer les tribus aborigènes et de les refouler vers la péninsule de Tasman.", "a7114cb5"]},
"OLAYLAR_UMIT19_ASIRET_1119:1830-11-26:0":{"b": ["La première série de l'opération de la Ligne noire prit officiellement fin : Ordre du gouvernement n° 13", "861ffa50"], "d": ["L'Ordre du gouvernement n° 13, daté du 26 novembre 1830, annonça que la première série d'opérations visant à capturer les tribus indigènes était close, les détachements militaires et civils ayant atteint East Bay Neck.", "a4f38ca9"]}
});
